// Prácticas guiadas del laboratorio de circuitos (módulo 3015, RA del Anexo IV, Orden 8-nov-2016).
import { sym as s, svg } from './schem.js';

const P = (id, type, where, rot = 0, props = {}, extra = {}) => ({ place: { id, type, ...(typeof where === 'string' ? { at: where } : { pos: where }), rot, props }, ...extra });
const W = (id, a, b, color, extra = {}) => ({ wire: { id, a, b, color }, ...extra });
const SIM = (extra = {}) => ({ sim: true, t: 'Inicia la simulación', text: 'Pulsa el botón verde <b>▶ Iniciar simulación</b> (arriba a la derecha).', ...extra });
const ACT = (part, test, t, text, extra = {}) => ({ act: { part, test }, t, text, ...extra });
const MEAS = (mode, red, com, t, text, extra = {}) => ({ measure: { mode, red, com }, t, text, ...extra });
const BAT4 = [P('B1', 'aa4', [-31, -1], 0, {}, { t: 'Coloca el portapilas', text: 'Arrastra el <b>portapilas 4×AA (6 V)</b> a la mesa, a la izquierda de la protoboard. Puede ir en cualquier sitio de la mesa.' }),
  W('w1', 'p:B1:+', 'h:tp2', 'rojo', { t: 'Cable rojo: + al carril +', text: 'Elige el cable <b>Dupont macho-hembra</b>: la hembra se encaja en la punta estañada del <b>cable rojo (+)</b> del portapilas y el macho se pincha en el <b>carril + de arriba</b> (línea roja). Así toda esa fila queda a +6 V.' }),
  W('w2', 'p:B1:-', 'h:tn2', 'negro', { t: 'Cable negro: − al carril −', text: 'Ahora, con otro macho-hembra, del <b>cable negro (−)</b> del portapilas al <b>carril − de arriba</b> (línea azul).' })];
const BAT9 = [P('B1', 'bat9', [-23, -5], 0, {}, { t: 'Coloca la pila de 9 V', text: 'Arrastra la <b>pila de 9 V</b> a la mesa, a la izquierda de la protoboard.' }),
  W('w1', 'p:B1:+', 'h:tp2', 'rojo', { t: 'Cable rojo: + al carril +', text: 'Elige el cable <b>cocodrilo-macho</b>: la pinza muerde el <b>borne +</b> (el pequeño y redondo) y el macho se pincha en el <b>carril + de arriba</b> (línea roja).' }),
  W('w2', 'p:B1:-', 'h:tn2', 'negro', { t: 'Cable negro: − al carril −', text: 'Otro <b>cocodrilo-macho</b>: pinza en el <b>borne −</b> (hexagonal) y macho en el <b>carril − de arriba</b> (línea azul).' })];

const BAT2 = [P('B1', 'aa2', [-27, -1], 0, {}, { t: 'Coloca el portapilas de 3 V', text: 'Arrastra el <b>portapilas 2×AA (3 V)</b> a la mesa, a la izquierda de la protoboard. Hace el papel de la pila de botón de 3 V de Tinkercad.' }),
  W('w1', 'p:B1:+', 'h:tp2', 'rojo', { t: 'Cable rojo: + al carril +', text: 'Con un cable <b>Dupont macho-hembra</b>, del <b>cable rojo (+)</b> del portapilas al <b>carril + de arriba</b> (línea roja).' }),
  W('w2', 'p:B1:-', 'h:tn2', 'negro', { t: 'Cable negro: − al carril −', text: 'Con otro macho-hembra, del <b>cable negro (−)</b> al <b>carril − de arriba</b> (línea azul).' })];

